mapper.update:
UPDATE qa_sessions
SET title = #{title}, updated_at = #{updatedAt}
WHERE id = #{id,jdbcType=OTHER}
  AND deleted_at IS NULL

UPDATE qa_sessions
SET updated_at = #{updatedAt}
WHERE id = #{id,jdbcType=OTHER}
  AND deleted_at IS NULL

UPDATE qa_sessions
SET deleted_at = #{deletedAt}
WHERE id = #{id,jdbcType=OTHER}
  AND deleted_at IS NULL

mapper.select:
SELECT COUNT(*) > 0
FROM qa_sessions
WHERE id      = #{id,jdbcType=OTHER}
  AND user_id = #{userId,jdbcType=OTHER}
  AND deleted_at IS NULL
